--[[
    VeevHUD - Italian (itIT) Localization

    AI-GENERATED translation (by Claude) -- NOT yet reviewed by a native speaker.

    >> Contributions welcome! << Spotted an awkward or wrong string? Edit its
    L["..."] = "..." value below and open a pull request (or an issue) at
    https://github.com/veev-code/VeevHUD  -- native speakers especially appreciated.
    Any key omitted here falls back to English automatically (see enUS.lua).
]]

local L = LibStub("AceLocale-3.0"):NewLocale("VeevHUD", "itIT")
if not L then return end

L["Outline"] = "Contorno"
L["Shadow"] = "Ombra"
L["Both"] = "Entrambi"
L["None"] = "Nessuno"
L["Inherit (Global)"] = "Eredita (globale)"
L["Off"] = "Disattivato"
L["Primary Row"] = "Riga primaria"
L["Primary + Secondary Rows"] = "Righe primaria + secondaria"
L["Secondary + Utility Rows"] = "Righe secondaria + utilità"
L["Utility Row"] = "Riga utilità"
L["All Rows"] = "Tutte le righe"
L["Prediction"] = "Previsione"
L["Fill"] = "Riempimento"
L["Bar"] = "Barra"
L["Spark"] = "Scintilla"
L["Current"] = "Attuale"
L["%"] = "%"
L["Current (%)"] = "Attuale (%)"
L["Current / Max"] = "Attuale / Max"
L["Current / Max (%)"] = "Attuale / Max (%)"
L["Deficit"] = "Deficit"
L["Abbreviated (4.5k)"] = "Abbreviato (4.5k)"
L["Full (4523)"] = "Completo (4523)"
L["Comma (4,523)"] = "Virgola (4,523)"
L["Default: "] = "Predefinito: "
L["Core rotation abilities used every fight — your most important cooldowns."] = "Abilità centrali della rotazione usate in ogni combattimento: i tuoi cooldown più importanti."
L["Throughput cooldowns, maintenance buffs, and situational damage or healing abilities."] = "Cooldown di throughput, buff di mantenimento e abilità di danno o cura situazionali."
L["Crowd control, interrupts, defensives, and movement abilities."] = "Controllo della folla, interruzioni, difensive e abilità di movimento."
L["Totems, trinkets, and other supplementary icons."] = "Totem, gingilli e altre icone supplementari."
L["Enabled"] = "Attivato"
L["Enables or disables this row. When disabled, abilities assigned to this row are hidden and the row takes no space on the HUD."] = "Attiva o disattiva questa riga. Quando disattivata, le abilità assegnate a questa riga sono nascoste e la riga non occupa spazio sull'HUD."
L["Size"] = "Dimensione"
L["Icon Size"] = "Dimensione icone"
L["The size of each ability icon in this row, in pixels. Each row can have different-sized icons — for example, larger icons for your main rotation and smaller ones for utility."] = "La dimensione di ciascuna icona di abilità in questa riga, in pixel. Ogni riga può avere icone di dimensioni diverse: ad esempio, icone più grandi per la rotazione principale e più piccole per l'utilità."
L["Max Icons"] = "Icone max"
L["The maximum number of ability icons that can appear in this row. If you assign more spells than this limit, the extra ones won't be shown."] = "Il numero massimo di icone di abilità che possono apparire in questa riga. Se assegni più incantesimi di questo limite, quelli in eccesso non verranno mostrati."
L["Aspect Ratio"] = "Proporzioni"
L["Override the icon shape for this row. |cffffffffInherit|r uses the global setting from Appearance."] = "Sovrascrivi la forma delle icone per questa riga. |cffffffffEredita|r usa l'impostazione globale da Aspetto."
L["Inherit"] = "Eredita"
L["Square (1:1)"] = "Quadrato (1:1)"
L["Slightly Compact"] = "Leggermente compatto"
L["Compact (4:3)"] = "Compatto (4:3)"
L["Very Compact"] = "Molto compatto"
L["Ultra Compact (2:1)"] = "Ultra compatto (2:1)"
L["Flow Layout"] = "Disposizione a flusso"
L["Wraps icons into multiple lines instead of displaying them all in a single long line. The Icons Per Row setting controls the maximum icons per line.\n\nTo avoid a sparse last row, icons are moved down from the previous row — for example, 8 icons at 6 per row becomes 5 and 3 instead of 6 and 2."] = "Dispone le icone su più righe invece di mostrarle tutte in un'unica lunga riga. L'impostazione Icone per riga controlla il numero massimo di icone per riga.\n\nPer evitare un'ultima riga semivuota, le icone vengono spostate in basso dalla riga precedente: ad esempio, 8 icone a 6 per riga diventano 5 e 3 invece di 6 e 2."
L["Icons Per Row"] = "Icone per riga"
L["The maximum number of icons on each line before wrapping to the next. Rows fill from the top, so earlier rows are always full.\n\nTo avoid a sparse last row, icons are moved down from the previous row — for example, 14 icons at 6 per row becomes 6, 5, 3 instead of 6, 6, 2."] = "Il numero massimo di icone su ciascuna riga prima di passare alla successiva. Le righe si riempiono dall'alto, quindi le prime righe sono sempre piene.\n\nPer evitare un'ultima riga semivuota, le icone vengono spostate in basso dalla riga precedente: ad esempio, 14 icone a 6 per riga diventano 6, 5, 3 invece di 6, 6, 2."
L["Reorder the vertical layout of the HUD and adjust spacing between elements."] = "Riordina la disposizione verticale dell'HUD e regola la spaziatura tra gli elementi."
L["Up"] = "Su"
L["Down"] = "Giù"
L["Gap above %s"] = "Spazio sopra %s"
L["Pixels of space between %s and %s."] = "Pixel di spazio tra %s e %s."
L["VeevHUD"] = "VeevHUD"
L["Version "] = "Versione "
L["General"] = "Generale"
L["Global settings that affect the entire HUD. Individual modules have their own tabs."] = "Impostazioni globali che influenzano l'intero HUD. I singoli moduli hanno le proprie schede."
L["Position and Scale"] = "Posizione e scala"
L["Horizontal Offset"] = "Spostamento orizzontale"
L["Moves the entire HUD left or right from the center of the screen. Negative values shift it left, positive values shift it right. The range adjusts to your screen resolution."] = "Sposta l'intero HUD a sinistra o a destra rispetto al centro dello schermo. I valori negativi lo spostano a sinistra, quelli positivi a destra. L'intervallo si adatta alla risoluzione dello schermo."
L["Vertical Offset"] = "Spostamento verticale"
L["Moves the entire HUD up or down on your screen. Negative values move it below center, positive values move it above. The range adjusts to your screen resolution."] = "Sposta l'intero HUD in alto o in basso sullo schermo. I valori negativi lo spostano sotto il centro, quelli positivi sopra. L'intervallo si adatta alla risoluzione dello schermo."
L["Scale"] = "Scala"
L["Makes everything in the HUD bigger or smaller. 100% is the normal size. Increase if you have trouble seeing the icons, decrease if they take up too much screen space."] = "Rende tutto nell'HUD più grande o più piccolo. 100% è la dimensione normale. Aumenta se hai difficoltà a vedere le icone, riduci se occupano troppo spazio sullo schermo."
L["Appearance"] = "Aspetto"
L["Font"] = "Carattere"
L["The font used for all text in the HUD, including cooldown timers, stack counts, health/resource values, and proc durations.\n\nIf you have font-sharing addons installed (SharedMedia, etc.), their fonts will appear here automatically."] = "Il carattere usato per tutto il testo nell'HUD, inclusi i timer dei cooldown, i conteggi delle pile, i valori di salute/risorse e le durate dei proc.\n\nSe hai installato addon di condivisione caratteri (SharedMedia, ecc.), i loro caratteri appariranno qui automaticamente."
L["Text Color"] = "Colore testo"
L["The color used for cooldown countdowns, duration timers, and stack counts across all HUD elements."] = "Il colore usato per i conti alla rovescia dei cooldown, i timer di durata e i conteggi delle pile in tutti gli elementi dell'HUD."
L["Text Outline"] = "Contorno testo"
L["Controls how text is rendered across all HUD elements.\n\n|cffffffffOutline|r — Font outline only.\n|cffffffffShadow|r — Drop shadow only (cleaner at small sizes).\n|cffffffffBoth|r — Font outline + drop shadow (maximum readability).\n|cffffffffNone|r — No outline or shadow.\n\nIndividual elements can override this in their own settings."] = "Controlla come viene reso il testo in tutti gli elementi dell'HUD.\n\n|cffffffffContorno|r — Solo contorno del carattere.\n|cffffffffOmbra|r — Solo ombra (più pulita a dimensioni ridotte).\n|cffffffffEntrambi|r — Contorno + ombra (massima leggibilità).\n|cffffffffNessuno|r — Nessun contorno o ombra.\n\nI singoli elementi possono sovrascrivere questa impostazione nelle proprie impostazioni."
L["Bar Texture"] = "Texture barra"
L["The texture used for all status bars in the HUD, including health, resource, combo point, and energy ticker bars.\n\nIf you have texture-sharing addons installed (SharedMedia, etc.), their textures will appear here automatically."] = "La texture usata per tutte le barre di stato nell'HUD, incluse le barre di salute, risorse, punti combo ed energia.\n\nSe hai installato addon di condivisione texture (SharedMedia, ecc.), le loro texture appariranno qui automaticamente."
L["Bar Gradient"] = "Gradiente barra"
L["Adds a subtle dark-to-light gradient across all status bars (health, resource, combo points, and energy ticker), giving them more visual depth instead of a flat solid color."] = "Aggiunge un sottile gradiente dal scuro al chiaro su tutte le barre di stato (salute, risorse, punti combo ed energia), conferendo loro maggiore profondità visiva invece di un colore piatto e uniforme."
L["Icon Zoom"] = "Zoom icone"
L["Zooms into each icon's artwork, cropping the edges. Affects ability rows and Aura Tracker. Useful for removing the default border that some spell textures have. 0% shows the full icon, 16% is a subtle crop."] = "Ingrandisce la grafica di ciascuna icona, ritagliando i bordi. Influisce sulle righe di abilità e sul Tracker Aura. Utile per rimuovere il bordo predefinito che alcune texture di incantesimo hanno. 0% mostra l'icona completa, 16% è un ritaglio sottile."
L["Sound"] = "Suono"
L["Sound Channel"] = "Canale audio"
L["Audio channel for all VeevHUD sound alerts.\n\n|cffffffffMaster|r — Always plays regardless of volume sliders.\n|cffffffffSound Effects|r — Respects the Sound Effects volume slider.\n|cffffffffMusic|r — Respects the Music volume slider.\n|cffffffffAmbience|r — Respects the Ambience volume slider."] = "Canale audio per tutti gli avvisi sonori di VeevHUD.\n\n|cffffffffMaster|r — Riproduce sempre indipendentemente dai cursori del volume.\n|cffffffffEffetti sonori|r — Rispetta il cursore del volume Effetti sonori.\n|cffffffffMusica|r — Rispetta il cursore del volume Musica.\n|cffffffffAmbiente|r — Rispetta il cursore del volume Ambiente."
L["Register Sound Kit ID"] = "Registra ID kit sonoro"
L["Enter a WoW Sound Kit ID (a number) to register it as an available sound. Once registered, it appears in all sound dropdowns.\n\nBrowse IDs at: wowhead.com/sounds\n\nExamples: 8959 (raid warning), 11466 (Illidan), 8174 (PvP flag).\n\nNote: the speaker preview button in dropdowns does not work for Kit IDs, but the sound plays correctly in-game."] = "Inserisci un ID kit sonoro di WoW (un numero) per registrarlo come suono disponibile. Una volta registrato, appare in tutti i menu a tendina dei suoni.\n\nSfoglia gli ID su: wowhead.com/sounds\n\nEsempi: 8959 (avviso raid), 11466 (Illidan), 8174 (bandiera PvP).\n\nNota: il pulsante di anteprima nei menu a tendina non funziona per gli ID kit, ma il suono viene riprodotto correttamente nel gioco."
L["Invalid Sound Kit ID: %s"] = "ID kit sonoro non valido: %s"
L["Playing Kit ID %s — registered as %s (top of sound dropdowns)."] = "Riproduzione ID kit %s: registrato come %s (in cima ai menu a tendina dei suoni)."
L["Sound Kit ID registration failed — LibSharedMedia not available."] = "Registrazione ID kit sonoro non riuscita: LibSharedMedia non disponibile."
L["Visibility"] = "Visibilità"
L["Out of Combat Opacity"] = "Opacità fuori combattimento"
L["Controls the HUD's visibility when not in combat. Use this to fade the HUD when out of combat so it's less distracting. 100% = fully visible, 50% = half transparent, 0% = invisible.\n\nNote: This setting is ignored while the config panel is open so you can see the HUD while configuring."] = "Controlla la visibilità dell'HUD quando non sei in combattimento. Usala per attenuare l'HUD fuori dal combattimento così è meno fastidioso. 100% = completamente visibile, 50% = semitrasparente, 0% = invisibile.\n\nNota: questa impostazione viene ignorata mentre il pannello di configurazione è aperto, così puoi vedere l'HUD mentre lo configuri."
L["Hide on Flight Path"] = "Nascondi sul tragitto di volo"
L["Automatically hides the HUD when you're on a flight path (taxi). The HUD will reappear when you land. Useful to keep your screen clean while traveling.\n\nNote: This setting is ignored while the config panel is open so you can see the HUD while configuring."] = "Nasconde automaticamente l'HUD quando sei su un tragitto di volo (taxi). L'HUD riapparirà all'atterraggio. Utile per mantenere lo schermo pulito durante i viaggi.\n\nNota: questa impostazione viene ignorata mentre il pannello di configurazione è aperto, così puoi vedere l'HUD mentre lo configuri."
L["Animations"] = "Animazioni"
L["Smooth Bar Animation"] = "Animazione fluida barre"
L["Health bars, resource bars, and the resource-cost overlay on ability icons animate smoothly instead of jumping when values change."] = "Le barre di salute, le barre delle risorse e l'overlay del costo in risorse sulle icone delle abilità si animano in modo fluido invece di saltare quando i valori cambiano."
L["Smooth Dim Transition"] = "Transizione attenuazione fluida"
L["When icons fade in or out (e.g., dimming on cooldown), the transition is gradual instead of instant. Disable for snappier visual feedback."] = "Quando le icone compaiono o scompaiono (es. attenuazione durante il cooldown), la transizione è graduale invece che istantanea. Disattiva per un feedback visivo più immediato."
L["Ability Rows"] = "Righe abilità"
L["Default visual settings for all ability rows. Individual rows can override icon shape in their own tabs."] = "Impostazioni visive predefinite per tutte le righe di abilità. Le singole righe possono sovrascrivere la forma delle icone nelle proprie schede."
L["Tip: Install the Masque addon to reskin ability icons with custom button styles."] = "Suggerimento: installa l'addon Masque per ridisegnare le icone delle abilità con stili di pulsante personalizzati."
L["Shape"] = "Forma"
L["Default icon shape for all ability rows. Individual rows can override this in their own settings. Aura Tracker has its own setting under Bars."] = "Forma predefinita delle icone per tutte le righe di abilità. Le singole righe possono sovrascriverla nelle proprie impostazioni. Il Tracker Aura ha la propria impostazione sotto Barre."
L["Spacing"] = "Spaziatura"
L["Icon Spacing"] = "Spaziatura icone"
L["The horizontal gap in pixels between each ability icon within a row. A small gap (2-4) helps visually separate icons. Set to 0 for icons to touch. Negative values allow overlap, which may look better with certain skins."] = "Lo spazio orizzontale in pixel tra ciascuna icona di abilità all'interno di una riga. Un piccolo spazio (2-4) aiuta a separare visivamente le icone. Imposta 0 per far toccare le icone. I valori negativi consentono la sovrapposizione, che può apparire meglio con certe skin."
L["Flow Row Spacing"] = "Spaziatura righe a flusso"
L["When a row uses flow layout and icons overflow to a second line, this is the vertical gap between lines."] = "Quando una riga usa la disposizione a flusso e le icone traboccano su una seconda riga, questo è lo spazio verticale tra le righe."
L["Opacity"] = "Opacità"
L["Ready Opacity"] = "Opacità pronto"
L["How visible icons are when the ability is ready to use. 100% means fully visible, lower values make ready abilities slightly transparent. Most people want this at 100%."] = "Quanto sono visibili le icone quando l'abilità è pronta all'uso. 100% significa completamente visibile, valori più bassi rendono le abilità pronte leggermente trasparenti. La maggior parte delle persone preferisce 100%."
L["Cooldown Opacity"] = "Opacità cooldown"
L["How visible icons are when on cooldown (for rows with Dim On Cooldown enabled). A lower value (like 30%) makes cooldown abilities fade out so you can focus on what's ready. Higher values keep them visible."] = "Quanto sono visibili le icone durante il cooldown (per le righe con Attenua durante cooldown attivo). Un valore più basso (come 30%) fa svanire le abilità in cooldown così puoi concentrarti su ciò che è pronto. Valori più alti le mantengono visibili."
L["Grey Out Unusable"] = "Ingrigisci inutilizzabili"
L["Makes icons grey when you don't have enough mana, rage, or energy to use the ability, or when you're in the wrong stance. Works the same way as WoW's default action bars.\n\nAutomatically disabled while resting in an inn or city to avoid constant grey-outs on combat abilities."] = "Rende grigie le icone quando non hai abbastanza Mana, Rabbia o Energia per usare l'abilità, o quando sei nella posizione sbagliata. Funziona come le barre delle azioni predefinite di WoW.\n\nDisattivato automaticamente mentre riposi in una locanda o in città per evitare continui ingrigimenti sulle abilità da combattimento."
L["Cooldowns"] = "Cooldown"
L["How cooldown information is displayed on ability icons."] = "Come vengono mostrate le informazioni sui cooldown sulle icone delle abilità."
L["Display"] = "Visualizzazione"
L["Cooldown Text"] = "Testo cooldown"
L["Displays the remaining cooldown time as numbers on top of each icon. When enabled, VeevHUD shows its own text and hides text from addons like OmniCC. Select which rows display cooldown text."] = "Mostra il tempo di cooldown rimanente come numeri sopra ciascuna icona. Quando attivo, VeevHUD mostra il proprio testo e nasconde quello di addon come OmniCC. Seleziona quali righe mostrano il testo del cooldown."
L["Text outline style for ability icon text (cooldowns, stacks, charges, keybinds)."] = "Stile del contorno del testo per le icone delle abilità (cooldown, pile, cariche, scorciatoie)."
L["Minutes Threshold"] = "Soglia minuti"
L["Remaining times above this many minutes are shown compactly. At the default of 2, 3 minutes 27 seconds is shown as 3m, while 1 minute 45 seconds is shown as 1:45."] = "I tempi rimanenti superiori a questo numero di minuti vengono mostrati in forma compatta. Con il valore predefinito di 2, 3 minuti e 27 secondi vengono mostrati come 3m, mentre 1 minuto e 45 secondi come 1:45."
L["Decimal Threshold"] = "Soglia decimali"
L["Remaining times below this many seconds are shown with one decimal. At the default of 2, 3.4 seconds is shown as 3, while 1.8 seconds is shown as 1.8."] = "I tempi rimanenti inferiori a questo numero di secondi vengono mostrati con un decimale. Con il valore predefinito di 2, 3.4 secondi vengono mostrati come 3, mentre 1.8 secondi come 1.8."
L["Cooldown Spiral"] = "Spirale cooldown"
L["Shows the dark 'clock sweep' overlay on abilities that are on cooldown. This visual helps you see at a glance how much time remains. Select which rows display the cooldown spiral."] = "Mostra l'overlay scuro a 'lancetta' sulle abilità in cooldown. Questo elemento visivo ti aiuta a vedere a colpo d'occhio quanto tempo rimane. Seleziona quali righe mostrano la spirale del cooldown."
L["Show GCD"] = "Mostra GCD"
L["Controls which rows display the Global Cooldown (GCD) spinner. The GCD is the brief ~1.5 second lockout after using most abilities. Showing GCD helps you see when you can press your next ability."] = "Controlla quali righe mostrano l'indicatore del cooldown globale (GCD). Il GCD è il breve blocco di circa 1.5 secondi dopo l'uso della maggior parte delle abilità. Mostrare il GCD ti aiuta a vedere quando puoi premere la prossima abilità."
L["Behavior"] = "Comportamento"
L["Dim On Cooldown"] = "Attenua durante cooldown"
L["Controls which rows fade out (become transparent) when abilities are on cooldown. The amount they fade is controlled by the |cffffffffCooldown Opacity|r setting.\n\nRows without dimming stay at full brightness and use greying-out to indicate unavailability instead. Many players keep the Primary row undimmed so their core rotation stays visually prominent."] = "Controlla quali righe svaniscono (diventano trasparenti) quando le abilità sono in cooldown. Il grado di attenuazione è controllato dall'impostazione |cffffffffOpacità cooldown|r.\n\nLe righe senza attenuazione rimangono a piena luminosità e usano invece l'ingrigimento per indicare l'indisponibilità. Molti giocatori mantengono la riga primaria non attenuata così la loro rotazione centrale resta visivamente in evidenza."
L["Cooldown Sparkle"] = "Scintillio cooldown"
L["Plays WoW's native sparkle animation when a cooldown finishes. Also triggers after the GCD, matching default action bar behavior. This is purely cooldown-based — it does not check resources or other usability conditions."] = "Riproduce l'animazione di scintillio nativa di WoW al termine di un cooldown. Si attiva anche dopo il GCD, replicando il comportamento delle barre delle azioni predefinite. È basato esclusivamente sul cooldown: non controlla risorse o altre condizioni di utilizzabilità."
L["Cooldown Spiral Opacity"] = "Opacità spirale cooldown"
L["How dark the spiral overlay appears during ability cooldowns. Lower values make it more subtle and transparent.\n\nNote: Even at 100%, the spiral won't completely obscure the icon — WoW's cooldown texture has built-in transparency."] = "Quanto scuro appare l'overlay a spirale durante i cooldown delle abilità. Valori più bassi lo rendono più sottile e trasparente.\n\nNota: anche al 100%, la spirale non oscurerà completamente l'icona: la texture del cooldown di WoW ha una trasparenza integrata."
L["Resources"] = "Risorse"
L["How resource costs (mana, rage, energy) are shown on ability icons."] = "Come vengono mostrati i costi in risorse (Mana, Rabbia, Energia) sulle icone delle abilità."
L["Display Mode"] = "Modalità visualizzazione"
L["How ability icons show whether you can afford to cast them:\n\n|cffffffffPrediction|r — Extends the cooldown sweep to include resource regeneration time. The icon shows how long until you can actually cast, accounting for both cooldown and resource cost. Energy and Mana predictions are tick-aware and very accurate. Rage falls back to Fill since rage income is unpredictable.\n\n|cffffffffFill|r — Darkens the icon from top to bottom proportional to missing resources. Simple and easy to read.\n\n|cffffffffBar|r — Shows a small colored bar at the bottom of each icon that fills up as you gain resources."] = "Come le icone delle abilità mostrano se puoi permetterti di lanciarle:\n\n|cffffffffPrevisione|r — Estende la lancetta del cooldown per includere il tempo di rigenerazione delle risorse. L'icona mostra quanto manca prima di poter effettivamente lanciare, tenendo conto sia del cooldown che del costo in risorse. Le previsioni per Energia e Mana sono consapevoli dei tick e molto accurate. La Rabbia ricade su Riempimento poiché il guadagno di rabbia è imprevedibile.\n\n|cffffffffRiempimento|r — Scurisce l'icona dall'alto in basso in proporzione alle risorse mancanti. Semplice e facile da leggere.\n\n|cffffffffBarra|r — Mostra una piccola barra colorata in fondo a ciascuna icona che si riempie man mano che guadagni risorse."
L["Show On Rows"] = "Mostra sulle righe"
L["Choose which rows show resource cost information on their icons. When enabled, you can see at a glance whether you have enough mana, rage, or energy to cast each ability."] = "Scegli quali righe mostrano le informazioni sul costo in risorse sulle loro icone. Quando attivo, puoi vedere a colpo d'occhio se hai abbastanza Mana, Rabbia o Energia per lanciare ciascuna abilità."
L["Show During Cooldowns"] = "Mostra durante i cooldown"
L["Shows the resource cost overlay on icons while they are on cooldown, so you can see your resource state through the cooldown spiral. When disabled, the resource overlay only appears when the ability is off cooldown."] = "Mostra l'overlay del costo in risorse sulle icone mentre sono in cooldown, così puoi vedere lo stato delle risorse attraverso la spirale del cooldown. Quando disattivato, l'overlay delle risorse appare solo quando l'abilità non è in cooldown."
L["Fill Style"] = "Stile riempimento"
L["Use Resource Color"] = "Usa colore risorsa"
L["Uses your resource type color for the fill overlay — red for rage, blue for mana, yellow for energy — instead of the custom Fill Color."] = "Usa il colore del tipo di risorsa per l'overlay di riempimento: rosso per la Rabbia, blu per il Mana, giallo per l'Energia, invece del colore di riempimento personalizzato."
L["Fill Color"] = "Colore riempimento"
L["The color of the resource cost fill overlay on icons. Default is black (a dark overlay showing missing resources). Only used when Use Resource Color is unchecked."] = "Il colore dell'overlay di riempimento del costo in risorse sulle icone. Il valore predefinito è nero (un overlay scuro che mostra le risorse mancanti). Usato solo quando Usa colore risorsa è disattivato."
L["Fill Opacity"] = "Opacità riempimento"
L["How opaque the resource cost overlay appears on icons. Higher values make it more obvious when you can't afford an ability. Applies to Fill mode and Prediction mode's fill fallback (used for rage and when predictions are unavailable)."] = "Quanto appare opaco l'overlay del costo in risorse sulle icone. Valori più alti rendono più evidente quando non puoi permetterti un'abilità. Si applica alla modalità Riempimento e al ripiego di riempimento della modalità Previsione (usato per la Rabbia e quando le previsioni non sono disponibili)."
L["Invert Fill"] = "Inverti riempimento"
L["Inverts the fill direction. Normal: overlay covers from top down showing missing resources. Inverted: overlay fills from bottom up showing current resources."] = "Inverte la direzione del riempimento. Normale: l'overlay copre dall'alto in basso mostrando le risorse mancanti. Invertito: l'overlay si riempie dal basso in alto mostrando le risorse attuali."
L["Bar Style"] = "Stile barra"
L["Uses your resource type color for the bar — red for rage, blue for mana, yellow for energy — instead of the custom Bar Color."] = "Usa il colore del tipo di risorsa per la barra: rosso per la Rabbia, blu per il Mana, giallo per l'Energia, invece del colore della barra personalizzato."
L["Bar Color"] = "Colore barra"
L["The color of the resource bar at the bottom of icons. Only used when Use Resource Color is unchecked."] = "Il colore della barra delle risorse in fondo alle icone. Usato solo quando Usa colore risorsa è disattivato."
L["Bar Height"] = "Altezza barra"
L["Height of the small resource bar shown at the bottom of each icon. Only visible when Display Mode is set to |cffffffffBar|r."] = "Altezza della piccola barra delle risorse mostrata in fondo a ciascuna icona. Visibile solo quando la Modalità visualizzazione è impostata su |cffffffffBarra|r."
L["Effects"] = "Effetti"
L["Visual effects on ability icons for active buffs, debuffs, and procs."] = "Effetti visivi sulle icone delle abilità per Buff, Debuff e proc attivi."
L["Aura Tracking"] = "Tracciamento aura"
L["Abilities that apply buffs or debuffs (like Intimidating Shout, Rend, Renew) show the active duration with a glow while the effect is on a target. After it expires, the cooldown is shown. Disable if you only want to see cooldowns."] = "Le abilità che applicano Buff o Debuff (come Intimidating Shout, Rend, Renew) mostrano la durata attiva con un bagliore mentre l'effetto è su un bersaglio. Dopo la scadenza, viene mostrato il cooldown. Disattiva se vuoi vedere solo i cooldown."
L["Target-of-Target Support"] = "Supporto bersaglio-del-bersaglio"
L["Also check for your buffs and debuffs on your target's target. Useful for healers tracking HoTs on the tank's target.\n\nExamples:\n- Target the boss, see your heals on the tank (the boss's target)\n- Target the tank, see your DoTs on the boss (the tank's target)"] = "Controlla i tuoi Buff e Debuff anche sul bersaglio del tuo bersaglio. Utile per i curatori che tracciano gli HoT sul bersaglio del tank.\n\nEsempi:\n- Bersaglia il boss, vedi le tue cure sul tank (il bersaglio del boss)\n- Bersaglia il tank, vedi i tuoi DoT sul boss (il bersaglio del tank)"
L["Aura Spiral Opacity"] = "Opacità spirale aura"
L["How dark the spiral overlay appears when tracking active buff or aura durations on icons. Lower values make it more subtle and transparent.\n\nNote: Even at 100%, the spiral won't completely obscure the icon — WoW's cooldown texture has built-in transparency."] = "Quanto scuro appare l'overlay a spirale quando si tracciano le durate di Buff o aura attivi sulle icone. Valori più bassi lo rendono più sottile e trasparente.\n\nNota: anche al 100%, la spirale non oscurerà completamente l'icona: la texture del cooldown di WoW ha una trasparenza integrata."
L["Cast Feedback"] = "Feedback di lancio"
L["Plays a brief 'pop' animation (the icon scales up slightly then back down) whenever you successfully cast an ability. Gives satisfying visual feedback that your spell went off. Select which rows show this animation."] = "Riproduce una breve animazione 'pop' (l'icona si ingrandisce leggermente e torna alla dimensione normale) ogni volta che lanci con successo un'abilità. Fornisce un soddisfacente feedback visivo che l'incantesimo è partito. Seleziona quali righe mostrano questa animazione."
L["Pop Scale"] = "Scala pop"
L["How much the icon briefly grows when you cast a spell. Higher values = bigger pop."] = "Di quanto cresce brevemente l'icona quando lanci un incantesimo. Valori più alti = pop più grande."
L["Ready Glow"] = "Bagliore pronto"
L["Shows a glowing border around ability icons when they come off cooldown and are ready to use. Only triggers while in combat. Select which rows display this effect."] = "Mostra un bordo luminoso attorno alle icone delle abilità quando escono dal cooldown e sono pronte all'uso. Si attiva solo durante il combattimento. Seleziona quali righe mostrano questo effetto."
L["Re-trigger Glow"] = "Riattiva bagliore"
L["Which rows re-trigger the glow whenever an ability becomes usable again (not just the first time).\n\nOn these rows, the glow plays again every time usability changes (e.g., gaining enough resources, target entering Execute range). Rows not selected here play the glow only once per cooldown cycle.\n\nNote: Reactive abilities (like Execute or Overpower) always re-trigger regardless of this setting."] = "Quali righe riattivano il bagliore ogni volta che un'abilità torna utilizzabile (non solo la prima volta).\n\nSu queste righe, il bagliore si riproduce di nuovo ogni volta che l'utilizzabilità cambia (es. ottenere abbastanza risorse, il bersaglio entra nel raggio di Execute). Le righe non selezionate qui riproducono il bagliore solo una volta per ciclo di cooldown.\n\nNota: le abilità reattive (come Execute o Overpower) si riattivano sempre indipendentemente da questa impostazione."
L["Duration"] = "Durata"
L["How long each ready glow animation lasts (in seconds). After this time, the glow fades out. On rows with Re-trigger Glow, the glow will re-trigger at this interval each time usability changes."] = "Quanto dura ciascuna animazione di bagliore pronto (in secondi). Dopo questo tempo, il bagliore svanisce. Sulle righe con Riattiva bagliore, il bagliore si riattiverà a questo intervallo ogni volta che l'utilizzabilità cambia."
L["Pre-trigger Time"] = "Tempo di pre-attivazione"
L["Begin the glow this many seconds before the cooldown completes, so you can prepare your next action. At 0, the glow only appears once the cooldown is fully complete."] = "Avvia il bagliore questo numero di secondi prima del completamento del cooldown, così puoi preparare la prossima azione. A 0, il bagliore appare solo quando il cooldown è completamente terminato."
L["Queued Highlight"] = "Evidenziazione in coda"
L["Brightens the icon of your next queued ability. Most noticeable on \"next melee\" attacks like Heroic Strike or Maul that stay queued until your next swing, but you may also see a brief flash on any ability queued during a cast or GCD."] = "Illumina l'icona della prossima abilità in coda. Più evidente sugli attacchi \"prossima mischia\" come Heroic Strike o Maul che restano in coda fino al prossimo colpo, ma potresti vedere un breve lampo anche su qualsiasi abilità messa in coda durante un lancio o il GCD."
L["Indicators"] = "Indicatori"
L["Range checking, sorting, and keybind display on ability icons."] = "Controllo della distanza, ordinamento e visualizzazione delle scorciatoie sulle icone delle abilità."
L["Range Indicator"] = "Indicatore di distanza"
L["Shows a red overlay on spell icons when your current target is out of range. Shows when an ability is usable but out of range — even during cooldown, giving you a heads-up on positioning. When resources are insufficient, the grey/resource indicators take priority instead.\n\nNote: Only shows when you have a target. Spells without a range component (self-buffs, etc.) are not affected."] = "Mostra un overlay rosso sulle icone degli incantesimi quando il bersaglio attuale è fuori portata. Si mostra quando un'abilità è utilizzabile ma fuori portata, anche durante il cooldown, dandoti un preavviso sul posizionamento. Quando le risorse sono insufficienti, gli indicatori grigio/risorsa hanno la precedenza.\n\nNota: si mostra solo quando hai un bersaglio. Gli incantesimi senza componente di distanza (auto-buff, ecc.) non sono interessati."
L["Dynamic Sorting"] = "Ordinamento dinamico"
L["Automatically reorders icons left-to-right by remaining cooldown, so abilities that are almost ready appear first.\n\nUseful for DOT classes (see which debuff is closest to expiring) and cooldown-heavy classes (see which ability is ready next).\n\nTie-breaker: When multiple abilities are ready, they sort by their original row position — so your row order acts as a priority list and the leftmost icon is always the next best spell to cast."] = "Riordina automaticamente le icone da sinistra a destra in base al cooldown rimanente, così le abilità quasi pronte appaiono per prime.\n\nUtile per le classi DoT (vedi quale Debuff è più vicino alla scadenza) e per le classi con molti cooldown (vedi quale abilità sarà pronta per prossima).\n\nSpareggio: quando più abilità sono pronte, vengono ordinate in base alla loro posizione originale nella riga, quindi l'ordine delle righe funge da elenco di priorità e l'icona più a sinistra è sempre il miglior incantesimo da lanciare."
L["Smooth Sorting"] = "Ordinamento fluido"
L["Icons slide smoothly into their new position when the sort order changes. Disable for instant repositioning."] = "Le icone scivolano in modo fluido nella loro nuova posizione quando l'ordinamento cambia. Disattiva per un riposizionamento istantaneo."
L["Keybinds"] = "Scorciatoie"
L["Displays the keyboard shortcut for each ability in the bottom-right corner. VeevHUD scans your action bars to find where each spell is placed. Modifiers are abbreviated: Shift=S, Ctrl=C, Alt=A (e.g., Shift+X becomes 'SX').\n\nSupports Bartender4, ElvUI, Dominos. If you move spells or change keybinds, the display updates automatically."] = "Mostra la scorciatoia da tastiera per ciascuna abilità nell'angolo in basso a destra. VeevHUD analizza le tue barre delle azioni per trovare dove è collocato ciascun incantesimo. I modificatori sono abbreviati: Shift=S, Ctrl=C, Alt=A (es. Shift+X diventa 'SX').\n\nSupporta Bartender4, ElvUI, Dominos. Se sposti incantesimi o cambi le scorciatoie, la visualizzazione si aggiorna automaticamente."
L["Text Size"] = "Dimensione testo"
L["The font size for keybind text in pixels. Larger values make the text more readable but take up more space on the icon."] = "La dimensione del carattere per il testo delle scorciatoie in pixel. Valori più grandi rendono il testo più leggibile ma occupano più spazio sull'icona."
L["Item Counts"] = "Conteggi oggetti"
L["Reagent Count"] = "Conteggio reagenti"
L["Shows the number of reagents you have in the top-right corner of spell icons that consume reagents on cast. Examples: Soul Shards on warlock abilities, seeds on Rebirth, Flash Powder on Vanish, Ankhs on Reincarnation."] = "Mostra il numero di reagenti che possiedi nell'angolo in alto a destra delle icone degli incantesimi che consumano reagenti al lancio. Esempi: Frammenti d'Anima sulle abilità del Warlock, semi per Rebirth, Polvere Lampo per Vanish, Ankh per Reincarnation."
L["Count All Ranks"] = "Conta tutti i ranghi"
L["When enabled, counts reagents for all spell ranks combined (e.g., all seed types for Rebirth). When disabled, only counts the reagent for your highest learned rank."] = "Quando attivo, conta i reagenti per tutti i ranghi dell'incantesimo combinati (es. tutti i tipi di seme per Rebirth). Quando disattivato, conta solo il reagente per il rango più alto che hai imparato."
L["Consumable Count"] = "Conteggio consumabili"
L["Shows your current bag count in the top-right corner of consumable icons (potions, runes, etc.)."] = "Mostra il numero attuale nella tua borsa nell'angolo in alto a destra delle icone dei consumabili (pozioni, rune, ecc.)."
L["Status Bars"] = "Barre di stato"
L["Resource Bar"] = "Barra delle risorse"
L["Your character's resource bar (mana, rage, or energy)."] = "La barra delle risorse del tuo personaggio (Mana, Rabbia o Energia)."
L["Shows a bar displaying your current mana, rage, or energy (depending on your class). Appears between the health bar and the ability icon rows."] = "Mostra una barra che visualizza Mana, Rabbia o Energia attuali (a seconda della classe). Appare tra la barra della salute e le righe delle icone delle abilità."
L["Width"] = "Larghezza"
L["How wide the resource bar is in pixels."] = "Quanto è larga la barra delle risorse in pixel."
L["Height"] = "Altezza"
L["How tall/thick the resource bar is in pixels. Changing this will automatically adjust the position of elements above it."] = "Quanto è alta/spessa la barra delle risorse in pixel. Modificarla regolerà automaticamente la posizione degli elementi sopra di essa."
L["Text"] = "Testo"
L["Text Format"] = "Formato testo"
L["Controls what text is shown on the resource bar.\n\n|cffffffffCurrent|r — Shows your actual resource (e.g., 4523).\n|cffffffffPercent|r — Shows your resource percentage (e.g., 85%).\n|cffffffffBoth|r — Shows both (e.g., 4523 (85%)).\n|cffffffffCurrent / Max|r — Shows current and maximum (e.g., 4523 / 5320).\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage (e.g., 4523 / 5320 (85%)).\n|cffffffffDeficit|r — Shows how much is missing (e.g., -797). Hidden at full.\n|cffffffffNone|r — Hides the text entirely."] = "Controlla quale testo viene mostrato sulla barra delle risorse.\n\n|cffffffffAttuale|r — Mostra la tua risorsa effettiva (es. 4523).\n|cffffffffPercentuale|r — Mostra la percentuale della risorsa (es. 85%).\n|cffffffffEntrambi|r — Mostra entrambi (es. 4523 (85%)).\n|cffffffffAttuale / Max|r — Mostra attuale e massimo (es. 4523 / 5320).\n|cffffffffAttuale / Max (%)|r — Mostra attuale, massimo e percentuale (es. 4523 / 5320 (85%)).\n|cffffffffDeficit|r — Mostra quanto manca (es. -797). Nascosto quando pieno.\n|cffffffffNessuno|r — Nasconde completamente il testo."
L["Number Format"] = "Formato numeri"
L["Controls how numbers are displayed.\n\n|cffffffffAbbreviated|r — Large numbers shortened (e.g., 4.5k, 1.2m).\n|cffffffffFull|r — Whole numbers (e.g., 4523).\n|cffffffffComma|r — Comma-separated (e.g., 4,523)."] = "Controlla come vengono visualizzati i numeri.\n\n|cffffffffAbbreviato|r — Numeri grandi accorciati (es. 4.5k, 1.2m).\n|cffffffffCompleto|r — Numeri interi (es. 4523).\n|cffffffffVirgola|r — Separati da virgola (es. 4,523)."
L["Font size for the resource text. Larger sizes are easier to read but may overflow small bars."] = "Dimensione del carattere per il testo delle risorse. Dimensioni più grandi sono più facili da leggere ma potrebbero traboccare dalle barre piccole."
L["Text outline style for the resource bar."] = "Stile del contorno del testo per la barra delle risorse."
L["Default Color"] = "Colore predefinito"
L["Colors the bar based on your resource type — blue for mana, red for rage, yellow for energy. Uncheck to use a custom color instead.\n\n"] = "Colora la barra in base al tipo di risorsa: blu per il Mana, rosso per la Rabbia, giallo per l'Energia. Deseleziona per usare invece un colore personalizzato.\n\n"
L["Overridden by Innervate Highlight (mana) and Rage Highlight (rage) when those are active."] = "Sovrascritto da Evidenziazione Innervate (mana) ed Evidenziazione rabbia (rabbia) quando questi sono attivi."
L["The custom color for the resource bar. Only used when Use Resource Color is unchecked.\n\n"] = "Il colore personalizzato per la barra delle risorse. Usato solo quando Usa colore risorsa è disattivato.\n\n"
L["Innervate Highlight"] = "Evidenziazione Innervate"
L["Changes the mana bar color when the Innervate buff is active, giving you immediate visual feedback that your mana regeneration is boosted."] = "Cambia il colore della barra del mana quando il buff Innervate è attivo, dandoti un feedback visivo immediato che la rigenerazione del mana è potenziata."
L["Color"] = "Colore"
L["The color the resource bar changes to during Innervate."] = "Il colore che assume la barra delle risorse durante Innervate."
L["Master toggle for rage bar coloring. When enabled, the bar changes color based on rage thresholds (e.g., flag rage cap risk) and when Heroic Strike or Cleave is queued onto your next swing."] = "Interruttore principale per la colorazione della barra della rabbia. Quando attivo, la barra cambia colore in base alle soglie di rabbia (es. segnalare il rischio di cap della rabbia) e quando Heroic Strike o Cleave è messo in coda sul prossimo colpo."
L["Rage Thresholds"] = "Soglie rabbia"
L["Threshold Coloring"] = "Colorazione a soglie"
L["Recolor the bar based on current rage. Three tiers (low/mid/high) gated by two thresholds."] = "Ricolora la barra in base alla rabbia attuale. Tre livelli (basso/medio/alto) delimitati da due soglie."
L["Low Threshold"] = "Soglia bassa"
L["Below this rage value, the bar uses the Low color. Above it (and below the High threshold), the Mid color."] = "Sotto questo valore di rabbia, la barra usa il colore Basso. Sopra di esso (e sotto la soglia Alta), il colore Medio."
L["High Threshold"] = "Soglia alta"
L["At or above this rage value, the bar uses the High color (e.g., bright red to flag rage cap risk)."] = "Pari o superiore a questo valore di rabbia, la barra usa il colore Alto (es. rosso acceso per segnalare il rischio di cap della rabbia)."
L["Low Color"] = "Colore basso"
L["Bar color when rage is below the Low threshold."] = "Colore della barra quando la rabbia è sotto la soglia Bassa."
L["Mid Color"] = "Colore medio"
L["Bar color when rage is between the Low and High thresholds."] = "Colore della barra quando la rabbia è tra la soglia Bassa e Alta."
L["High Color"] = "Colore alto"
L["Bar color when rage is at or above the High threshold."] = "Colore della barra quando la rabbia è pari o superiore alla soglia Alta."
L["Queued Ability Override"] = "Sovrascrittura abilità in coda"
L["Queue Override"] = "Sovrascrittura coda"
L["When a swing-reset ability (Heroic Strike, Cleave, Maul) is queued onto your next swing, override the threshold color with a per-ability color."] = "Quando un'abilità che reimposta il colpo (Heroic Strike, Cleave, Maul) è messa in coda sul prossimo colpo, sovrascrivi il colore della soglia con un colore specifico per abilità."
L["Bar color when %s is queued onto your next swing."] = "Colore della barra quando %s è messo in coda sul prossimo colpo."
L["Rage Highlight"] = "Evidenziazione rabbia"
L["Shows a bright highlight at the bar's current fill point — the glowing line where the filled and empty portions meet. Adds visual polish."] = "Mostra un'evidenziazione luminosa nel punto di riempimento attuale della barra: la linea luminosa dove si incontrano le porzioni piena e vuota. Aggiunge rifinitura visiva."
L["How wide the spark highlight is in pixels. Larger values create a broader, more prominent glow."] = "Quanto è larga l'evidenziazione a scintilla in pixel. Valori più grandi creano un bagliore più ampio e prominente."
L["Overflow"] = "Eccedenza"
L["How far the spark glow extends beyond the top and bottom edges of the bar (in pixels). Higher values create a taller spark that 'overflows' past the bar."] = "Quanto si estende il bagliore della scintilla oltre i bordi superiore e inferiore della barra (in pixel). Valori più alti creano una scintilla più alta che 'trabocca' oltre la barra."
L["Hide at Full/Empty"] = "Nascondi quando piena/vuota"
L["Hides the spark when the bar is completely full or completely empty, since there's no meaningful fill point to highlight in those states."] = "Nasconde la scintilla quando la barra è completamente piena o completamente vuota, poiché in quegli stati non c'è un punto di riempimento significativo da evidenziare."
L["Overlays"] = "Overlay"
L["Predicted Cost"] = "Costo previsto"
L["Shows a darkened section on the resource bar representing the cost of abilities you are currently casting or have queued (e.g., Heroic Strike, Cleave). Gives you a preview of where your resource will be after the ability completes."] = "Mostra una sezione scurita sulla barra delle risorse che rappresenta il costo delle abilità che stai lanciando o hai messo in coda (es. Heroic Strike, Cleave). Ti dà un'anteprima di dove sarà la tua risorsa dopo il completamento dell'abilità."
L["Energy Ticker"] = "Indicatore energia"
L["Shows progress toward the next energy tick (energy regenerates every 2 seconds). Helps you time abilities to maximize energy efficiency."] = "Mostra il progresso verso il prossimo tick di energia (l'energia si rigenera ogni 2 secondi). Ti aiuta a sincronizzare le abilità per massimizzare l'efficienza dell'energia."
L["Style"] = "Stile"
L["|cffffffffTicker Bar|r — Shows a separate thin bar below the resource bar that fills as the next tick approaches.\n\n|cffffffffSpark|r — Shows a moving spark overlay on the resource bar itself, which is more subtle."] = "|cffffffffBarra indicatore|r — Mostra una barra sottile separata sotto la barra delle risorse che si riempie all'avvicinarsi del prossimo tick.\n\n|cffffffffScintilla|r — Mostra un overlay a scintilla mobile sulla barra delle risorse stessa, più discreto."
L["Show at Full Energy"] = "Mostra a energia piena"
L["Keep the tick indicator running even when at full energy. Useful for timing openers — you can see exactly when the next tick will occur and use energy right before it arrives."] = "Mantieni in funzione l'indicatore dei tick anche a energia piena. Utile per sincronizzare le aperture: puoi vedere esattamente quando avverrà il prossimo tick e usare l'energia appena prima del suo arrivo."
L["Bar Settings"] = "Impostazioni barra"
L["How tall the energy ticker bar is in pixels."] = "Quanto è alta la barra dell'indicatore energia in pixel."
L["Bar Offset"] = "Spostamento barra"
L["Moves the energy ticker bar up or down relative to the resource bar. Positive values move it down, negative values move it up."] = "Sposta la barra dell'indicatore energia in alto o in basso rispetto alla barra delle risorse. I valori positivi la spostano in basso, quelli negativi in alto."
L["The color used for the energy ticker bar."] = "Il colore usato per la barra dell'indicatore energia."
L["Spark Settings"] = "Impostazioni scintilla"
L["Spark Width"] = "Larghezza scintilla"
L["How wide the tick spark is in pixels."] = "Quanto è larga la scintilla del tick in pixel."
L["Spark Height"] = "Altezza scintilla"
L["How tall the tick spark is relative to the resource bar. Values above 1.0 make the spark extend beyond the bar edges."] = "Quanto è alta la scintilla del tick rispetto alla barra delle risorse. Valori superiori a 1.0 fanno estendere la scintilla oltre i bordi della barra."
L["Mana Ticker"] = "Indicatore mana"
L["Shows a moving spark on the resource bar indicating when your next mana tick will arrive. Mana regenerates in periodic ticks, and casting at the wrong time can delay your next tick — this indicator helps you cast at the optimal moment."] = "Mostra una scintilla mobile sulla barra delle risorse che indica quando arriverà il prossimo tick di mana. Il mana si rigenera in tick periodici, e lanciare al momento sbagliato può ritardare il prossimo tick: questo indicatore ti aiuta a lanciare nel momento ottimale."
L["|cffffffffOutside 5 Second Rule|r — Only shows the tick timer when you haven't cast a spell in the last 5 seconds (when you're getting full spirit-based mana regeneration).\n\n|cffffffffNext Full Tick|r (Recommended) — Always active. After you cast a spell, it predicts exactly when your first full-rate mana tick will arrive and counts down to it. Cast right after the tick completes to get the most mana before your next spell."] = "|cffffffffFuori dalla regola dei 5 secondi|r — Mostra il timer del tick solo quando non hai lanciato un incantesimo negli ultimi 5 secondi (quando ricevi la piena rigenerazione del mana basata sullo spirito).\n\n|cffffffffProssimo tick pieno|r (consigliato) — Sempre attivo. Dopo aver lanciato un incantesimo, prevede esattamente quando arriverà il primo tick di mana a pieno regime e fa il conto alla rovescia. Lancia subito dopo il completamento del tick per ottenere più mana prima del prossimo incantesimo."
L["How wide the mana tick spark is in pixels."] = "Quanto è larga la scintilla del tick di mana in pixel."
L["How tall the mana tick spark is relative to the resource bar. Values above 1.0 make it extend beyond the bar edges."] = "Quanto è alta la scintilla del tick di mana rispetto alla barra delle risorse. Valori superiori a 1.0 la fanno estendere oltre i bordi della barra."
L["Mana Bar (Druid)"] = "Barra del mana (Druido)"
L["Shows a secondary mana bar below the resource bar while in Cat Form or Bear Form, so you can monitor mana for shifting and casting."] = "Mostra una barra del mana secondaria sotto la barra delle risorse mentre sei in Forma Felina o Forma Orso, così puoi monitorare il mana per i cambi di forma e i lanci."
L["Show a secondary mana bar below the resource bar while shapeshifted."] = "Mostra una barra del mana secondaria sotto la barra delle risorse mentre sei trasformato."
L["How tall the secondary mana bar is in pixels."] = "Quanto è alta la barra del mana secondaria in pixel."
L["Show Spark"] = "Mostra scintilla"
L["Shows a glowing spark at the current fill position on the mana bar."] = "Mostra una scintilla luminosa nella posizione di riempimento attuale sulla barra del mana."
L["The color used for the secondary mana bar."] = "Il colore usato per la barra del mana secondaria."
L["Show Mana Ticker"] = "Mostra indicatore mana"
L["Shows the mana tick spark on this bar while in form. When disabled, the mana ticker only appears on the main resource bar in caster form."] = "Mostra la scintilla del tick di mana su questa barra mentre sei in forma. Quando disattivato, l'indicatore del mana appare solo sulla barra delle risorse principale in forma da lanciatore."
L["Form Cost Marker"] = "Indicatore costo forma"
L["Shows a vertical line on the mana bar when your mana is too low to re-enter your current shapeshift form. The line indicates the mana threshold needed, so you can see how close you are to being able to shift back."] = "Mostra una linea verticale sulla barra del mana quando il tuo mana è troppo basso per rientrare nella forma attuale. La linea indica la soglia di mana necessaria, così puoi vedere quanto sei vicino a poter tornare nella forma."
L["Controls what text is shown on the Druid mana bar.\n\n|cffffffffCurrent|r — Shows your actual mana.\n|cffffffffPercent|r — Shows your mana percentage.\n|cffffffffBoth|r — Shows both.\n|cffffffffCurrent / Max|r — Shows current and maximum.\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage.\n|cffffffffDeficit|r — Shows how much is missing. Hidden at full.\n|cffffffffNone|r — Hides the text."] = "Controlla quale testo viene mostrato sulla barra del mana del Druido.\n\n|cffffffffAttuale|r — Mostra il tuo mana effettivo.\n|cffffffffPercentuale|r — Mostra la percentuale del mana.\n|cffffffffEntrambi|r — Mostra entrambi.\n|cffffffffAttuale / Max|r — Mostra attuale e massimo.\n|cffffffffAttuale / Max (%)|r — Mostra attuale, massimo e percentuale.\n|cffffffffDeficit|r — Mostra quanto manca. Nascosto quando pieno.\n|cffffffffNessuno|r — Nasconde il testo."
L["Controls how numbers are displayed."] = "Controlla come vengono visualizzati i numeri."
L["Font size for the mana bar text."] = "Dimensione del carattere per il testo della barra del mana."
L["Text outline style for the druid mana bar."] = "Stile del contorno del testo per la barra del mana del druido."
L["Health Bar"] = "Barra della salute"
L["Your character's health bar with heal prediction."] = "La barra della salute del tuo personaggio con previsione delle cure."
L["Shows a bar displaying your current health above the resource bar. Gives you a quick glance at your survivability without looking at your unit frame."] = "Mostra una barra che visualizza la tua salute attuale sopra la barra delle risorse. Ti dà un rapido sguardo alla tua sopravvivenza senza guardare il tuo riquadro unità."
L["How wide the health bar is in pixels."] = "Quanto è larga la barra della salute in pixel."
L["How tall/thick the health bar is in pixels. Changing this will automatically adjust the position of elements above it."] = "Quanto è alta/spessa la barra della salute in pixel. Modificarla regolerà automaticamente la posizione degli elementi sopra di essa."
L["Controls what text is shown on the health bar.\n\n|cffffffffCurrent|r — Shows your actual health (e.g., 3256).\n|cffffffffPercent|r — Shows your health percentage (e.g., 71%).\n|cffffffffBoth|r — Shows both (e.g., 3256 (71%)).\n|cffffffffCurrent / Max|r — Shows current and maximum (e.g., 3256 / 4580).\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage (e.g., 3256 / 4580 (71%)).\n|cffffffffDeficit|r — Shows how much health is missing (e.g., -1324). Hidden at full.\n|cffffffffNone|r — Hides the text entirely."] = "Controlla quale testo viene mostrato sulla barra della salute.\n\n|cffffffffAttuale|r — Mostra la tua salute effettiva (es. 3256).\n|cffffffffPercentuale|r — Mostra la percentuale di salute (es. 71%).\n|cffffffffEntrambi|r — Mostra entrambi (es. 3256 (71%)).\n|cffffffffAttuale / Max|r — Mostra attuale e massimo (es. 3256 / 4580).\n|cffffffffAttuale / Max (%)|r — Mostra attuale, massimo e percentuale (es. 3256 / 4580 (71%)).\n|cffffffffDeficit|r — Mostra quanta salute manca (es. -1324). Nascosto quando piena.\n|cffffffffNessuno|r — Nasconde completamente il testo."
L["Font size for the health text. Larger sizes are easier to read but may overflow small bars."] = "Dimensione del carattere per il testo della salute. Dimensioni più grandi sono più facili da leggere ma potrebbero traboccare dalle barre piccole."
L["Text outline style for the health bar."] = "Stile del contorno del testo per la barra della salute."
L["Use Class Color"] = "Usa colore classe"
L["Colors the health bar using your class color (e.g., brown for Warriors, purple for Warlocks) instead of the standard green."] = "Colora la barra della salute usando il colore della tua classe (es. marrone per i Guerrieri, viola per gli Stregoni) invece del verde standard."
L["The custom color for the health bar. Only used when Use Class Color is unchecked."] = "Il colore personalizzato per la barra della salute. Usato solo quando Usa colore classe è disattivato."
L["Heal Prediction"] = "Previsione cure"
L["Shows a lighter overlay on the health bar representing incoming heals. The overlay extends from your current health into the missing health area, giving you a preview of where your health will be after heals land."] = "Mostra un overlay più chiaro sulla barra della salute che rappresenta le cure in arrivo. L'overlay si estende dalla tua salute attuale nell'area di salute mancante, dandoti un'anteprima di dove sarà la tua salute dopo che le cure saranno applicate."
L["Pet Health Bar"] = "Barra salute del pet"
L["Your pet's health bar. Automatically hides when no pet is active."] = "La barra della salute del tuo pet. Si nasconde automaticamente quando nessun pet è attivo."
L["Shows a bar displaying your pet's current health. Automatically hides when you have no active pet."] = "Mostra una barra che visualizza la salute attuale del tuo pet. Si nasconde automaticamente quando non hai un pet attivo."
L["How wide the pet health bar is in pixels."] = "Quanto è larga la barra della salute del pet in pixel."
L["How tall/thick the pet health bar is in pixels."] = "Quanto è alta/spessa la barra della salute del pet in pixel."
L["Controls what text is shown on the pet health bar.\n\n|cffffffffCurrent|r — Shows actual health.\n|cffffffffPercent|r — Shows health percentage.\n|cffffffffBoth|r — Shows both.\n|cffffffffCurrent / Max|r — Shows current and maximum.\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage.\n|cffffffffDeficit|r — Shows how much health is missing. Hidden at full.\n|cffffffffNone|r — Hides the text."] = "Controlla quale testo viene mostrato sulla barra della salute del pet.\n\n|cffffffffAttuale|r — Mostra la salute effettiva.\n|cffffffffPercentuale|r — Mostra la percentuale di salute.\n|cffffffffEntrambi|r — Mostra entrambi.\n|cffffffffAttuale / Max|r — Mostra attuale e massimo.\n|cffffffffAttuale / Max (%)|r — Mostra attuale, massimo e percentuale.\n|cffffffffDeficit|r — Mostra quanta salute manca. Nascosto quando piena.\n|cffffffffNessuno|r — Nasconde il testo."
L["Font size for the pet health text."] = "Dimensione del carattere per il testo della salute del pet."
L["Text outline style for the pet health bar."] = "Stile del contorno del testo per la barra della salute del pet."
L["The color for the pet health bar."] = "Il colore per la barra della salute del pet."
L["Shows a lighter overlay on the pet health bar representing incoming heals."] = "Mostra un overlay più chiaro sulla barra della salute del pet che rappresenta le cure in arrivo."
L["Combo Points"] = "Punti combo"
L["Horizontal combo point display below the resource bar."] = "Visualizzazione orizzontale dei punti combo sotto la barra delle risorse."
L["Shows combo point bars below the resource bar. For Druids, this only appears while in Cat Form."] = "Mostra le barre dei punti combo sotto la barra delle risorse. Per i Druidi, appare solo in Forma Felina."
L["Size & Layout"] = "Dimensione e disposizione"
L["The total width of the combo points display in pixels."] = "La larghezza totale della visualizzazione dei punti combo in pixel."
L["The height of each combo point bar in pixels. Smaller values create a more subtle display."] = "L'altezza di ciascuna barra di punto combo in pixel. Valori più piccoli creano una visualizzazione più discreta."
L["Bar Spacing"] = "Spaziatura barre"
L["The gap in pixels between each individual combo point segment."] = "Lo spazio in pixel tra ciascun singolo segmento di punto combo."
L["The color used for active combo point segments."] = "Il colore usato per i segmenti di punto combo attivi."
L["Aura Tracker"] = "Tracker Aura"
L["The Aura Tracker shows small icons for important temporary buffs — class procs (Enrage, Flurry, Clearcasting), external buffs (Bloodlust, Power Infusion, Innervate), and any custom auras you add.\n\nUse the tabs above to configure which auras to show."] = "Il Tracker Aura mostra piccole icone per i Buff temporanei importanti: proc di classe (Enrage, Flurry, Clearcasting), buff esterni (Bloodlust, Power Infusion, Innervate) e qualsiasi aura personalizzata tu aggiunga.\n\nUsa le schede sopra per configurare quali aure mostrare."
L["Enable Aura Tracker"] = "Attiva Tracker Aura"
L["Master toggle for the Aura Tracker feature. When disabled, no aura icons will be shown."] = "Interruttore principale per la funzione Tracker Aura. Quando disattivato, nessuna icona di aura verrà mostrata."
L["Layout"] = "Disposizione"
L["How big the aura icons are in pixels. These are typically smaller than ability icons since they're just indicators. 20-28 pixels works well for most people."] = "Quanto sono grandi le icone delle aure in pixel. Di solito sono più piccole delle icone delle abilità poiché sono semplici indicatori. 20-28 pixel funziona bene per la maggior parte delle persone."
L["The gap in pixels between each aura icon when multiple auras are active at once."] = "Lo spazio in pixel tra ciascuna icona di aura quando più aure sono attive contemporaneamente."
L["Makes aura icons shorter by shrinking height while keeping width the same. Useful if you want compact spell rows but prefer aura icons to stay more square and readable."] = "Rende le icone delle aure più basse riducendo l'altezza mantenendo invariata la larghezza. Utile se vuoi righe di incantesimi compatte ma preferisci che le icone delle aure restino più quadrate e leggibili."
L["Glow"] = "Bagliore"
L["Edge Glow"] = "Bagliore dei bordi"
L["Shows a glowing animated border around active aura icons, making them stand out and drawing your eye to important buffs."] = "Mostra un bordo animato luminoso attorno alle icone delle aure attive, facendole risaltare e attirando il tuo sguardo sui buff importanti."
L["Backdrop Intensity"] = "Intensità sfondo"
L["Controls the brightness of the soft colored halo that appears behind each aura icon. Higher values make the glow more prominent. Set to 0 to turn it off completely."] = "Controlla la luminosità del morbido alone colorato che appare dietro ciascuna icona di aura. Valori più alti rendono il bagliore più prominente. Imposta 0 per disattivarlo completamente."
L["Backdrop Size"] = "Dimensione sfondo"
L["How far the backdrop glow extends outward from each aura icon. Larger values create a wider, softer halo."] = "Quanto si estende verso l'esterno il bagliore di sfondo da ciascuna icona di aura. Valori più grandi creano un alone più ampio e morbido."
L["Animation"] = "Animazione"
L["Show Duration"] = "Mostra durata"
L["Displays the remaining time on aura buffs as text on the icon. Disable if you prefer a cleaner look or if it overlaps with stack counts."] = "Mostra il tempo rimanente sui buff aura come testo sull'icona. Disattiva se preferisci un aspetto più pulito o se si sovrappone ai conteggi delle pile."
L["Text outline style for aura tracker text."] = "Stile del contorno del testo per il testo del tracker aura."
L["Slide Animation"] = "Animazione di scorrimento"
L["When auras appear or disappear, the remaining icons smoothly slide to re-center instead of snapping instantly. Disable for instant repositioning."] = "Quando le aure compaiono o scompaiono, le icone rimanenti scivolano in modo fluido per ricentrarsi invece di scattare istantaneamente. Disattiva per un riposizionamento istantaneo."
L["Activation Pop"] = "Pop di attivazione"
L["How much the icon briefly grows when an aura activates or refreshes. Set to 100% to disable the pop animation."] = "Di quanto cresce brevemente l'icona quando un'aura si attiva o si rinnova. Imposta 100% per disattivare l'animazione pop."
L["Sort Order"] = "Ordinamento"
L["How active aura icons are arranged.\n\n|cffffffffActivation Order|r — First-activated aura appears on the left, newest on the right.\n\n|cffffffffFixed|r — Icons stay in a consistent order based on spell registration (class procs first, then externals, then custom).\n\n|cffffffffLeast Remaining|r — Aura closest to expiring appears on the left. Icons re-sort as durations tick down."] = "Come vengono disposte le icone delle aure attive.\n\n|cffffffffOrdine di attivazione|r — L'aura attivata per prima appare a sinistra, la più recente a destra.\n\n|cffffffffFisso|r — Le icone restano in un ordine coerente basato sulla registrazione degli incantesimi (prima i proc di classe, poi gli esterni, poi i personalizzati).\n\n|cffffffffMeno rimanente|r — L'aura più vicina alla scadenza appare a sinistra. Le icone si riordinano man mano che le durate diminuiscono."
L["Activation Order"] = "Ordine di attivazione"
L["Fixed"] = "Fisso"
L["Least Remaining"] = "Meno rimanente"
L["Bars"] = "Barre"
L["Auras set to \"Bar\" mode (via the Display dropdown in the aura list tabs) render as a vertical stack of timer bars below the icon row. These settings control how those bars look."] = "Le aure impostate in modalità \"Barra\" (tramite il menu a tendina Visualizzazione nelle schede dell'elenco aure) vengono mostrate come una pila verticale di barre timer sotto la riga delle icone. Queste impostazioni controllano l'aspetto di quelle barre."
L["Bar Width"] = "Larghezza barra"
L["Width of each timer bar in pixels."] = "Larghezza di ciascuna barra timer in pixel."
L["Height of each timer bar in pixels. The spell icon is sized to match."] = "Altezza di ciascuna barra timer in pixel. L'icona dell'incantesimo viene dimensionata di conseguenza."
L["Vertical gap in pixels between stacked bars."] = "Spazio verticale in pixel tra le barre impilate."
L["Font size for the bar's name and timer text."] = "Dimensione del carattere per il nome e il testo del timer della barra."
L["Text outline style for bar text."] = "Stile del contorno del testo per il testo della barra."
L["Fallback fill color for bars whose spell has no icon-sampled color (most do). Each aura's color is normally taken from its icon; you can override per aura in the aura list tabs."] = "Colore di riempimento di ripiego per le barre il cui incantesimo non ha un colore campionato dall'icona (la maggior parte ce l'ha). Il colore di ciascuna aura viene normalmente preso dalla sua icona; puoi sovrascriverlo per ogni aura nelle schede dell'elenco aure."
L["Show Icon"] = "Mostra icona"
L["Show the spell icon at the left edge of each bar."] = "Mostra l'icona dell'incantesimo sul bordo sinistro di ciascuna barra."
L["Show Name"] = "Mostra nome"
L["Show the aura name on each bar."] = "Mostra il nome dell'aura su ciascuna barra."
L["Show Timer"] = "Mostra timer"
L["Show the remaining-time text on each bar."] = "Mostra il testo del tempo rimanente su ciascuna barra."
L["Show a spark at the fill edge of each bar."] = "Mostra una scintilla sul bordo di riempimento di ciascuna barra."
L["Default Sound"] = "Suono predefinito"
L["Sound to play when any aura activates. Individual auras can override this in the aura list tabs."] = "Suono da riprodurre quando una qualsiasi aura si attiva. Le singole aure possono sovrascriverlo nelle schede dell'elenco aure."
L["Play on Refresh"] = "Riproduci al rinnovo"
L["Also play the sound when an aura refreshes (is reapplied while already active). Useful for procs like Mace Stun where each trigger matters. Individual auras can override this in the aura list tabs."] = "Riproduci il suono anche quando un'aura si rinnova (viene riapplicata mentre è già attiva). Utile per proc come Mace Stun dove ogni attivazione conta. Le singole aure possono sovrascriverlo nelle schede dell'elenco aure."
L["Swing Bar"] = "Barra dei colpi"
L["Your character automatically fires auto-shots on a timer. If you cast an ability too late in the timer, it 'clips' (delays) your next auto-shot, costing you DPS. The bar turns green when it's safe to cast and red when casting would clip. Once you learn Steady Shot, a yellow zone appears for the window where Steady Shot would clip but instants and movement are still safe."] = "Il tuo personaggio spara automaticamente colpi automatici a tempo. Se lanci un'abilità troppo tardi nel timer, 'taglia' (ritarda) il prossimo colpo automatico, costandoti DPS. La barra diventa verde quando è sicuro lanciare e rossa quando lanciare taglierebbe. Una volta imparato Steady Shot, appare una zona gialla per la finestra in cui Steady Shot taglierebbe ma gli istantanei e il movimento sono ancora sicuri."
L["Seal twisting lets you get two seal procs on a single melee swing by swapping seals right before the hit lands. The bar turns green during the twist window — the last ~0.4 seconds before impact — telling you when to swap to your second seal."] = "Il seal twisting ti permette di ottenere due proc di sigillo su un singolo colpo in mischia scambiando i sigilli proprio prima che il colpo vada a segno. La barra diventa verde durante la finestra di twist, gli ultimi ~0.4 secondi prima dell'impatto, indicandoti quando passare al secondo sigillo."
L["Tracks your melee swing timer — a bar that fills up as your next auto-attack approaches. Auto-hides between pulls."] = "Traccia il timer dei tuoi colpi in mischia: una barra che si riempie all'avvicinarsi del prossimo attacco automatico. Si nasconde automaticamente tra un pull e l'altro."
L["Two bars track your main-hand and off-hand swing timers. When both weapons swing at the same time (synced), your Flurry haste charges aren't wasted on isolated off-hand hits, and Windfury extra attacks land alongside your normal swings. Bars turn green when synced and red when desynced — meaning one weapon has drifted ahead of the other."] = "Due barre tracciano i timer dei colpi della mano principale e della mano secondaria. Quando entrambe le armi colpiscono nello stesso momento (sincronizzate), le cariche di celerità di Flurry non vengono sprecate su colpi isolati della mano secondaria, e gli attacchi extra di Windfury vanno a segno insieme ai colpi normali. Le barre diventano verdi quando sincronizzate e rosse quando desincronizzate, ovvero quando un'arma è in anticipo rispetto all'altra."
L["Tracks your melee swing timer. Slam resets this timer, so for maximum DPS you want to Slam right after a swing lands (when the bar reaches the end and resets). This avoids losing auto-attack time to the Slam cast.\n\n"] = "Traccia il timer dei tuoi colpi in mischia. Slam reimposta questo timer, quindi per il massimo DPS conviene usare Slam subito dopo che un colpo va a segno (quando la barra raggiunge la fine e si reimposta). Così si evita di perdere tempo di attacco automatico per il lancio di Slam.\n\n"
L["Tracks your melee swing timer — a bar that fills up as your next auto-attack approaches. Auto-hides between pulls.\n\n"] = "Traccia il timer dei tuoi colpi in mischia: una barra che si riempie all'avvicinarsi del prossimo attacco automatico. Si nasconde automaticamente tra un pull e l'altro.\n\n"
L["Tracks your auto-attack timer for wanding or melee. Only appears while actively attacking and auto-hides when you stop."] = "Traccia il timer del tuo attacco automatico per la bacchetta o la mischia. Appare solo mentre attacchi attivamente e si nasconde automaticamente quando ti fermi."
L["Tracks your melee swing timer. Shows separate main-hand and off-hand bars when dual-wielding."] = "Traccia il timer dei tuoi colpi in mischia. Mostra barre separate per la mano principale e la mano secondaria quando usi due armi."
L["Tracks your melee swing timer in Cat or Bear Form. Bear Form's 2.5s swing is useful for timing Maul. Auto-hides when not actively swinging."] = "Traccia il timer dei tuoi colpi in mischia in Forma Felina o Forma Orso. Il colpo da 2.5s della Forma Orso è utile per sincronizzare Maul. Si nasconde automaticamente quando non stai colpendo attivamente."
L["Shows a weapon swing timer bar that fills as your next auto-attack approaches. Includes class-specific colored zones: Hunter shot clipping, Ret Paladin seal twisting, Enhancement/Warrior dual-wield sync. Auto-hides when not actively swinging."] = "Mostra una barra del timer dei colpi dell'arma che si riempie all'avvicinarsi del prossimo attacco automatico. Include zone colorate specifiche per classe: taglio dei colpi del Cacciatore, seal twisting del Paladino Punizione, sincronizzazione a due armi di Potenziamento/Guerriero. Si nasconde automaticamente quando non stai colpendo attivamente."
L["Width of the swing bar in pixels."] = "Larghezza della barra dei colpi in pixel."
L["Height of the swing bar in pixels (single weapon). Per-class/spec: each class or spec remembers its own height."] = "Altezza della barra dei colpi in pixel (arma singola). Per classe/spec: ogni classe o spec ricorda la propria altezza."
L["Wand Height"] = "Altezza bacchetta"
L["Height of the swing bar in pixels for wand users (Mage, Priest, Warlock)."] = "Altezza della barra dei colpi in pixel per gli utenti di bacchetta (Mago, Sacerdote, Stregone)."
L["Dual-Wield Height"] = "Altezza a due armi"
L["Height of each bar when dual-wielding (MH and OH bars shown separately)."] = "Altezza di ciascuna barra quando usi due armi (barre della mano principale e secondaria mostrate separatamente)."
L["Dual-Wield Spacing"] = "Spaziatura a due armi"
L["Gap in pixels between the main-hand and off-hand bars."] = "Spazio in pixel tra le barre della mano principale e della mano secondaria."
L["Show a glowing spark at the fill edge of the bar."] = "Mostra una scintilla luminosa sul bordo di riempimento della barra."
L["Hide Delay"] = "Ritardo nascondi"
L["Seconds to wait after the last swing before auto-hiding the bar."] = "Secondi di attesa dopo l'ultimo colpo prima di nascondere automaticamente la barra."
L["The fill color of the swing bar. Disabled when class-specific coloring overrides the entire bar."] = "Il colore di riempimento della barra dei colpi. Disattivato quando la colorazione specifica della classe sovrascrive l'intera barra."
L["Timer Text"] = "Testo timer"
L["Show Timer Text"] = "Mostra testo timer"
L["Show a countdown timer on the bar."] = "Mostra un timer di conto alla rovescia sulla barra."
L["Font size for the timer text."] = "Dimensione del carattere per il testo del timer."
L["Text outline style for the swing bar."] = "Stile del contorno del testo per la barra dei colpi."
L["Class Options"] = "Opzioni di classe"
L["Enable Shot Zones"] = "Attiva zone di tiro"
L["Color the bar by auto-shot timing:\n\n|cffffffffGreen|r — Safe to cast anything and move freely.\n|cffffffffYellow|r — Steady Shot would clip, but instants and movement are safe.\n|cffffffffRed|r — Don't move or cast Multi-Shot (auto-shot animation playing)."] = "Colora la barra in base alla sincronizzazione del colpo automatico:\n\n|cffffffffVerde|r — Sicuro lanciare qualsiasi cosa e muoversi liberamente.\n|cffffffffGiallo|r — Steady Shot taglierebbe, ma gli istantanei e il movimento sono sicuri.\n|cffffffffRosso|r — Non muoverti e non lanciare Multi-Shot (animazione del colpo automatico in corso)."
L["Safe Zone (Green)"] = "Zona sicura (verde)"
L["Bar color when it's safe to cast and move."] = "Colore della barra quando è sicuro lanciare e muoversi."
L["Steady Zone (Yellow)"] = "Zona Steady (gialla)"
L["Bar color when Steady Shot would clip, but instant shots and movement are still safe."] = "Colore della barra quando Steady Shot taglierebbe, ma i colpi istantanei e il movimento sono ancora sicuri."
L["Stop Zone (Red)"] = "Zona di stop (rossa)"
L["Bar color when moving would cancel your auto-shot and Multi-Shot would clip."] = "Colore della barra quando muoversi annullerebbe il colpo automatico e Multi-Shot taglierebbe."
L["Enable Twist Window"] = "Attiva finestra di twist"
L["Highlight the last ~0.4 seconds before your melee swing with a different color — your cue to swap seals for seal twisting."] = "Evidenzia gli ultimi ~0.4 secondi prima del tuo colpo in mischia con un colore diverso: il segnale per scambiare i sigilli nel seal twisting."
L["Twist Window Color"] = "Colore finestra di twist"
L["Bar color during the seal twist window."] = "Colore della barra durante la finestra di seal twist."
L["Zone Opacity"] = "Opacità zone"
L["Opacity of the background zone indicators that preview upcoming color changes on the bar."] = "Opacità degli indicatori di zona sullo sfondo che anticipano i prossimi cambi di colore sulla barra."
L["Melee Weaving"] = "Intreccio mischia"
L["Show both ranged and melee swing bars simultaneously. For advanced hunters who weave melee attacks (e.g., Raptor Strike) between auto-shots."] = "Mostra contemporaneamente le barre dei colpi a distanza e in mischia. Per i cacciatori esperti che intrecciano attacchi in mischia (es. Raptor Strike) tra i colpi automatici."
L["Enable Sync Colors"] = "Attiva colori di sincronizzazione"
L["Sync Threshold"] = "Soglia di sincronizzazione"
L["Spell Config"] = "Config. incantesimi"
L["Spells"] = "Incantesimi"
L["Click the button below to open the spell configuration window — enable/disable spells, reorder them, and drag between rows."] = "Fai clic sul pulsante qui sotto per aprire la finestra di configurazione degli incantesimi: attiva/disattiva incantesimi, riordinali e trascinali tra le righe."
L["Open Spell Configuration"] = "Apri configurazione incantesimi"
L["Opens the spell configuration window where you can enable/disable spells, reorder them, and move them between rows using drag-and-drop."] = "Apre la finestra di configurazione degli incantesimi dove puoi attivare/disattivare incantesimi, riordinarli e spostarli tra le righe tramite il trascinamento."
L["Consumables"] = "Consumabili"
L["Track combat consumables on your HUD — potions, runes, and other items you use mid-fight. Each icon shows the item cooldown, buff duration, and bag count. For long-duration pre-pull buffs (elixirs, flasks, food), use a consumable-tracking addon like NovaConsumesHelper."] = "Traccia i consumabili da combattimento sull'HUD: pozioni, rune e altri oggetti che usi durante il combattimento. Ogni icona mostra il cooldown dell'oggetto, la durata del buff e il conteggio nella borsa. Per i buff pre-pull a lunga durata (elisir, fiale, cibo), usa un addon di tracciamento dei consumabili come NovaConsumesHelper."
L["Spec not yet detected"] = "Spec non ancora rilevata"
L["Add Consumables"] = "Aggiungi consumabili"
L["Add by Item ID"] = "Aggiungi per ID oggetto"
L["Enter an item ID to track any consumable not listed above. You can find item IDs on Wowhead (the number in the URL) or with the idTip addon."] = "Inserisci un ID oggetto per tracciare qualsiasi consumabile non elencato sopra. Puoi trovare gli ID oggetto su Wowhead (il numero nell'URL) o con l'addon idTip."
L["Invalid input — enter a numeric item ID."] = "Input non valido: inserisci un ID oggetto numerico."
L["Added:"] = "Aggiunto:"
L["Tracked Consumables"] = "Consumabili tracciati"
L["Sounds"] = "Suoni"
L["Play a sound when an ability becomes ready — when it comes off cooldown, becomes usable, or meets resource requirements. Set a default sound for all abilities, or override individual spells below.\n\nSound plays for all rows regardless of the Ready Glow row filter. Other settings still apply: combat-only, pre-trigger time, and once vs. re-trigger mode."] = "Riproduci un suono quando un'abilità diventa pronta: quando esce dal cooldown, diventa utilizzabile o soddisfa i requisiti di risorse. Imposta un suono predefinito per tutte le abilità, oppure sovrascrivi i singoli incantesimi qui sotto.\n\nIl suono viene riprodotto per tutte le righe indipendentemente dal filtro delle righe del Bagliore pronto. Le altre impostazioni si applicano comunque: solo in combattimento, tempo di pre-attivazione e modalità una volta o riattivazione."
L["Support"] = "Supporto"
L["Veev Addons Discord"] = "Veev Addons Discord"
L["Discord URL"] = "URL Discord"
L["Press Ctrl+C to copy the URL."] = "Premi Ctrl+C per copiare l'URL."
L["VeevHUD is built with a $200/mo Claude subscription, late-night coding sessions, and unhealthy amounts of caffeine. I code for the love of the game, not for profit. Donations to help offset the costs are appreciated but never expected!"] = "VeevHUD è realizzato con un abbonamento Claude da 200 $/mese, sessioni di programmazione notturne e quantità malsane di caffeina. Programmo per amore del gioco, non per profitto. Le donazioni per aiutare a coprire i costi sono apprezzate ma mai pretese!"
L["Donate URL"] = "URL donazioni"
L["Cooldown Pulse"] = "Pulsazione cooldown"
L["Flashes a large icon in the center of the screen when a tracked ability comes off cooldown. A prominent visual cue that complements the ready glow on ability icons."] = "Fa lampeggiare una grande icona al centro dello schermo quando un'abilità tracciata esce dal cooldown. Un segnale visivo prominente che integra il bagliore pronto sulle icone delle abilità."
L["Enable Cooldown Pulse"] = "Attiva pulsazione cooldown"
L["Master toggle for the cooldown pulse effect. When enabled, a large icon briefly flashes on screen each time a tracked ability finishes its cooldown."] = "Interruttore principale per l'effetto pulsazione cooldown. Quando attivo, una grande icona lampeggia brevemente sullo schermo ogni volta che un'abilità tracciata termina il suo cooldown."
L["How large the flashing icon appears on screen, in pixels."] = "Quanto grande appare l'icona lampeggiante sullo schermo, in pixel."
L["Peak opacity of the icon during the flash. Lower values create a more subtle, ghostly effect."] = "Opacità massima dell'icona durante il lampeggio. Valori più bassi creano un effetto più sottile e spettrale."
L["X Offset"] = "Spostamento X"
L["Horizontal offset from the center of your screen. Negative values move left, positive values move right."] = "Spostamento orizzontale dal centro dello schermo. I valori negativi spostano a sinistra, quelli positivi a destra."
L["Y Offset"] = "Spostamento Y"
L["Vertical offset from the center of your screen. Negative values move down, positive values move up."] = "Spostamento verticale dal centro dello schermo. I valori negativi spostano in basso, quelli positivi in alto."
L["Filtering"] = "Filtraggio"
L["Which ability rows trigger the cooldown pulse. Primary Row is your core rotation — the most impactful notifications. Add Secondary to include throughput cooldowns too."] = "Quali righe di abilità attivano la pulsazione del cooldown. La Riga primaria è la tua rotazione centrale: le notifiche di maggiore impatto. Aggiungi Secondaria per includere anche i cooldown di throughput."
L["Only In Combat"] = "Solo in combattimento"
L["Only show cooldown pulses while you are in combat."] = "Mostra le pulsazioni del cooldown solo mentre sei in combattimento."
L["Ignore Cooldowns Below"] = "Ignora cooldown inferiori a"
L["Skip pulses for abilities with cooldowns shorter than this. Useful for filtering out short-cooldown rotational spells. Set to 0 to include everything."] = "Salta le pulsazioni per le abilità con cooldown più brevi di questo valore. Utile per filtrare gli incantesimi di rotazione con cooldown breve. Imposta 0 per includere tutto."
L["Fade In Effect"] = "Effetto di comparsa"
L["Size effect while the icon fades in. Grow: starts small, grows to normal. Shrink: starts big, shrinks to normal. None: no size change."] = "Effetto di dimensione mentre l'icona compare. Cresci: parte piccola, cresce fino al normale. Restringi: parte grande, si restringe fino al normale. Nessuno: nessun cambio di dimensione."
L["Grow"] = "Cresci"
L["Shrink"] = "Restringi"
L["Fade Out Effect"] = "Effetto di scomparsa"
L["Size effect while the icon fades out. Grow: grows from normal to big. Shrink: shrinks from normal to small. None: no size change."] = "Effetto di dimensione mentre l'icona scompare. Cresci: cresce dal normale al grande. Restringi: si restringe dal normale al piccolo. Nessuno: nessun cambio di dimensione."
L["Fade In"] = "Comparsa"
L["How long the icon takes to fade in, in seconds."] = "Quanto tempo impiega l'icona a comparire, in secondi."
L["Hold Time"] = "Tempo di permanenza"
L["How long the icon stays at peak opacity before fading out. Set to 0 for a quick flash, or increase for a longer notification."] = "Quanto tempo l'icona resta alla massima opacità prima di scomparire. Imposta 0 per un lampo rapido, o aumenta per una notifica più lunga."
L["Fade Out"] = "Scomparsa"
L["How long the icon takes to fade out, in seconds."] = "Quanto tempo impiega l'icona a scomparire, in secondi."
L["Early Trigger"] = "Attivazione anticipata"
L["Fire the pulse this many seconds before the cooldown finishes. Gives you a head start on reacting. Set to 0 to pulse at the exact moment the ability becomes ready."] = "Attiva la pulsazione questo numero di secondi prima del termine del cooldown. Ti dà un vantaggio per reagire. Imposta 0 per pulsare nell'esatto momento in cui l'abilità diventa pronta."
L["Test Pulse"] = "Prova pulsazione"
L["Plays a test pulse so you can preview your current settings."] = "Riproduce una pulsazione di prova così puoi vedere in anteprima le impostazioni attuali."
L["No consumables added yet. Select one from the dropdowns above."] = "Nessun consumabile ancora aggiunto. Selezionane uno dai menu a tendina sopra."
L["Remove"] = "Rimuovi"
L["Remove this consumable from tracking."] = "Rimuovi questo consumabile dal tracciamento."
L["Any"] = "Qualsiasi"
L["Own"] = "Proprio"
L["Others"] = "Altri"
L["Icon"] = "Icona"
L["Show this aura as a compact icon in the icon row, or as a status bar with name and timer in the bar stack below the icons."] = "Mostra questa aura come icona compatta nella riga delle icone, oppure come barra di stato con nome e timer nella pila di barre sotto le icone."
L["Fill color for this aura's timer bar (Bar display mode only). Defaults to a vibrant color sampled from the spell's icon — change it here to override."] = "Colore di riempimento per la barra timer di questa aura (solo in modalità Barra). Per impostazione predefinita usa un colore vivace campionato dall'icona dell'incantesimo: cambialo qui per sovrascriverlo."
L["Toggle which class procs are tracked. Enabled procs appear as icons in the Aura Tracker when active."] = "Attiva/disattiva quali proc di classe vengono tracciati. I proc attivati appaiono come icone nel Tracker Aura quando sono attivi."
L["Show this aura in the tracker."] = "Mostra questa aura nel tracker."
L["Show the glowing border and backdrop halo when this aura is active. Disable for auras you want to track quietly without the glow drawing your eye."] = "Mostra il bordo luminoso e l'alone di sfondo quando questa aura è attiva. Disattiva per le aure che vuoi tracciare in modo discreto senza che il bagliore attiri il tuo sguardo."
L["Sound to play when this aura activates. 'None' uses the global default from the Sound section above."] = "Suono da riprodurre quando questa aura si attiva. 'Nessuno' usa il valore predefinito globale dalla sezione Suono sopra."
L["Refresh"] = "Aggiorna"
L["Also play the sound when this aura refreshes (is reapplied while already active)."] = "Riproduci il suono anche quando questa aura si rinnova (viene riapplicata mentre è già attiva)."
L["Settings"] = "Impostazioni"
L["Class Procs"] = "Proc di classe"
L["External Buffs"] = "Buff esterni"
L["Custom Auras"] = "Aure personalizzate"
L["Toggle which external buffs are tracked (from other players, consumables, or PvP powerups). These appear as icons in the Aura Tracker when active on you."] = "Attiva/disattiva quali buff esterni vengono tracciati (da altri giocatori, consumabili o potenziamenti PvP). Questi appaiono come icone nel Tracker Aura quando sono attivi su di te."
L["Track %s (ID: %s)"] = "Traccia %s (ID: %s)"
L["Show the glowing border and backdrop halo when this aura is active."] = "Mostra il bordo luminoso e l'alone di sfondo quando questa aura è attiva."
L["Sound to play when this aura activates. 'None' uses the global default."] = "Suono da riprodurre quando questa aura si attiva. 'Nessuno' usa il valore predefinito globale."
L["Also play the sound when this aura refreshes."] = "Riproduci il suono anche quando questa aura si rinnova."
L["Add custom auras to track by spell ID or spell name. These work like procs — the icon appears when the buff is active on you."] = "Aggiungi aure personalizzate da tracciare per ID o nome dell'incantesimo. Funzionano come i proc: l'icona appare quando il buff è attivo su di te."
L["Spell ID or Name"] = "ID o nome incantesimo"
L["Enter a numeric spell ID or exact spell name and press Enter to add.\n\nYou can find spell IDs on Wowhead (the number at the end of the spell URL), or install the idTip addon to see spell IDs directly in tooltips."] = "Inserisci un ID incantesimo numerico o il nome esatto dell'incantesimo e premi Invio per aggiungere.\n\nPuoi trovare gli ID incantesimo su Wowhead (il numero alla fine dell'URL dell'incantesimo), o installare l'addon idTip per vedere gli ID incantesimo direttamente nei tooltip."
L["(icon shows when buff is active)"] = "(l'icona appare quando il buff è attivo)"
L["(by name — icon shows when buff is active)"] = "(per nome: l'icona appare quando il buff è attivo)"
L["Current Custom Auras"] = "Aure personalizzate attuali"
L["Recently Seen Buffs"] = "Buff visti di recente"
L["No custom auras added yet."] = "Nessuna aura personalizzata ancora aggiunta."
L["(ID: "] = "(ID: "
L["Del"] = "Elim."
L["Remove this custom aura."] = "Rimuovi questa aura personalizzata."
L["No recent buffs recorded yet. Play for a bit and reopen this tab."] = "Nessun buff recente ancora registrato. Gioca un po' e riapri questa scheda."
L["All recent buffs are already tracked."] = "Tutti i buff recenti sono già tracciati."
L["Add"] = "Aggiungi"
L["In Combat"] = "In combattimento"
L["Out of Combat"] = "Fuori combattimento"
L["Player"] = "Giocatore"
L["Party"] = "Gruppo"
L["Raid"] = "Incursione"
L["Enable or disable this buff reminder."] = "Attiva o disattiva questo promemoria di buff."
L["Time Threshold"] = "Soglia di tempo"
L["Show the reminder when the buff has less than this many seconds remaining. Set to 0 to only remind when the buff is completely missing."] = "Mostra il promemoria quando al buff rimangono meno di questo numero di secondi. Imposta 0 per ricordare solo quando il buff manca completamente."
L["Combat"] = "Combattimento"
L["When to show this reminder based on combat state."] = "Quando mostrare questo promemoria in base allo stato di combattimento."
L["Track"] = "Traccia"
L["Who to check for this buff.\n\n|cffffffffPlayer|r: Only check yourself.\n|cffffffffParty|r: Check all party members (or only yourself if solo).\n|cffffffffRaid|r: Check all raid members (downsizes to party if not in a raid)."] = "Chi controllare per questo buff.\n\n|cffffffffGiocatore|r: Controlla solo te stesso.\n|cffffffffGruppo|r: Controlla tutti i membri del gruppo (o solo te stesso se da solo).\n|cffffffffIncursione|r: Controlla tutti i membri dell'incursione (si riduce al gruppo se non sei in un'incursione)."
L["Sound to play when this buff reminder appears. 'None' uses the global default from the General tab."] = "Suono da riprodurre quando appare questo promemoria di buff. 'Nessuno' usa il valore predefinito globale dalla scheda Generale."
L["Min Stacks"] = "Pile min"
L["Show the reminder when stacks fall below this number. Set to 0 to disable stack checking. This is an OR condition with the time threshold."] = "Mostra il promemoria quando le pile scendono sotto questo numero. Imposta 0 per disattivare il controllo delle pile. Questa è una condizione OR con la soglia di tempo."
L["Priority"] = "Priorità"
L["Which spell to remind first when no buff from this group is active."] = "Quale incantesimo ricordare per primo quando nessun buff di questo gruppo è attivo."
L["Main Hand"] = "Mano principale"
L["Show a reminder when your main hand weapon is missing an enchant. Disable this if you prefer to benefit from a Shaman's Windfury Totem instead."] = "Mostra un promemoria quando alla tua arma nella mano principale manca un incantamento. Disattivalo se preferisci beneficiare invece del Totem Windfury di uno Sciamano."
L["Off Hand"] = "Mano secondaria"
L["Show a reminder when your off hand weapon is missing an enchant."] = "Mostra un promemoria quando alla tua arma nella mano secondaria manca un incantamento."
L["Configure which buff reminders are active. Settings on this tab are per-spec — switching specs loads that spec's configuration."] = "Configura quali promemoria di buff sono attivi. Le impostazioni di questa scheda sono per spec: cambiando spec viene caricata la configurazione di quella spec."
L["Show Only Known Spells"] = "Mostra solo incantesimi conosciuti"
L["Only shows spells you currently know. Disable to see all class buff spells, including ones you haven't learned yet."] = "Mostra solo gli incantesimi che conosci attualmente. Disattiva per vedere tutti gli incantesimi di buff della classe, inclusi quelli che non hai ancora imparato."
L["Buff Reminders"] = "Promemoria buff"
L["Buff Reminders show a large, semi-transparent icon when a long-duration buff you should maintain is missing or about to expire. They are separate from the main HUD icons and only appear when action is needed.\n\nReminders automatically check that you know the spell and have the resources to cast it. Use the Spells tab to configure individual reminders."] = "I Promemoria buff mostrano una grande icona semitrasparente quando un buff a lunga durata che dovresti mantenere manca o sta per scadere. Sono separati dalle icone principali dell'HUD e appaiono solo quando è necessaria un'azione.\n\nI promemoria controllano automaticamente che tu conosca l'incantesimo e abbia le risorse per lanciarlo. Usa la scheda Incantesimi per configurare i singoli promemoria."
L["Enable Buff Reminders"] = "Attiva promemoria buff"
L["Master toggle for the Buff Reminders feature. When disabled, no buff reminder icons will be shown."] = "Interruttore principale per la funzione Promemoria buff. Quando disattivato, nessuna icona di promemoria buff verrà mostrata."
L["The size of buff reminder icons in pixels."] = "La dimensione delle icone dei promemoria buff in pixel."
L["The horizontal gap between buff reminder icons."] = "Lo spazio orizzontale tra le icone dei promemoria buff."
L["Icon Opacity"] = "Opacità icone"
L["The opacity of the buff reminder icons."] = "L'opacità delle icone dei promemoria buff."
L["Text outline style for buff reminder text."] = "Stile del contorno del testo per il testo dei promemoria buff."
L["Pulse Animation"] = "Animazione di pulsazione"
L["Reminder icons gently pulse to draw attention."] = "Le icone dei promemoria pulsano delicatamente per attirare l'attenzione."
L["Respect Resource Cost"] = "Rispetta costo risorse"
L["Only show buff reminders when you have enough resources (mana, rage, energy) to cast the spell. Uncheck to always show reminders for missing buffs regardless of your current resource level."] = "Mostra i promemoria buff solo quando hai abbastanza risorse (Mana, Rabbia, Energia) per lanciare l'incantesimo. Deseleziona per mostrare sempre i promemoria dei buff mancanti indipendentemente dal tuo livello attuale di risorse."
L["Show While Resting"] = "Mostra mentre riposi"
L["Show buff reminders while in inns and cities."] = "Mostra i promemoria buff mentre sei nelle locande e nelle città."
L["Show While Mounted"] = "Mostra mentre cavalchi"
L["Show buff reminders while mounted."] = "Mostra i promemoria buff mentre cavalchi."
L["When buff reminders appear or disappear, the remaining icons smoothly slide to re-center instead of snapping instantly. Disable for instant repositioning."] = "Quando i promemoria buff compaiono o scompaiono, le icone rimanenti scivolano in modo fluido per ricentrarsi invece di scattare istantaneamente. Disattiva per un riposizionamento istantaneo."
L["Click to Cast (Out of Combat)"] = "Clic per lanciare (fuori combattimento)"
L["Makes reminder icons clickable — left-click casts the missing buff. Blizzard restricts addon casting to secure buttons that cannot be moved, shown, or hidden during combat, so clicking only works out of combat — in combat, reminders are visual-only and clicks pass through as normal."] = "Rende cliccabili le icone dei promemoria — il clic sinistro lancia il potenziamento mancante. Blizzard consente agli addon di lanciare incantesimi solo tramite pulsanti sicuri che in combattimento non possono essere spostati, mostrati o nascosti, quindi il clic funziona solo fuori dal combattimento — in combattimento i promemoria sono puramente visivi e i clic passano attraverso normalmente."
L["Sound to play when a buff reminder first appears. Individual spells can override this in the Spells tab."] = "Suono da riprodurre quando un promemoria buff appare per la prima volta. I singoli incantesimi possono sovrascriverlo nella scheda Incantesimi."
L["Position"] = "Posizione"
L["Horizontal offset of buff reminder icons relative to the HUD. The range adjusts to your screen resolution."] = "Spostamento orizzontale delle icone dei promemoria buff rispetto all'HUD. L'intervallo si adatta alla risoluzione dello schermo."
L["Vertical offset of buff reminder icons relative to the HUD. The range adjusts to your screen resolution."] = "Spostamento verticale delle icone dei promemoria buff rispetto all'HUD. L'intervallo si adatta alla risoluzione dello schermo."
L["Toggle a sample buff reminder icon so you can see your settings in action."] = "Attiva un'icona di promemoria buff di esempio così puoi vedere le tue impostazioni in azione."
L["Default"] = "Predefinito"
L["Sound to play when the ready glow activates on any ability. Per-spell overrides below take priority."] = "Suono da riprodurre quando il bagliore pronto si attiva su una qualsiasi abilità. Le sovrascritture per incantesimo qui sotto hanno la precedenza."
L["Primary"] = "Primaria"
L["Secondary"] = "Secondaria"
L["Utility"] = "Utilità"
L["Auxiliary"] = "Ausiliaria"
L["VeevHUD |TInterface\\Icons\\Spell_Nature_Reincarnation:16:16|t"] = "VeevHUD |TInterface\\Icons\\Spell_Nature_Reincarnation:16:16|t"
