L["Unknown command. Type /vh help for usage."] = "Comando sconosciuto. Digita /vh help per l'utilizzo."
L["Commands:"] = "Comandi:"
L["Open settings panel"] = "Apri il pannello impostazioni"
L["Reset to defaults"] = "Ripristina i valori predefiniti"
L["Enable/disable HUD"] = "Attiva/disattiva HUD"
