-- Strings added in the 2026-08 localization coverage pass.
-- AI-generated (Claude); native-speaker review welcome.
L["HUD Stack"] = "Pila HUD"
L["Only attached elements appear here. Reorder them from top to bottom and tune the space between each pair."] = "Qui appaiono solo gli elementi agganciati. Riordinali dall'alto verso il basso e regola lo spazio tra ogni coppia."
L["Move Rows"] = "Sposta righe"
L["Detach any ability row from the HUD stack, then drag it anywhere on the screen. While this tab is open, detached rows show drag handles and other HUD elements close the vacated space automatically."] = "Sgancia qualsiasi riga di abilità dalla pila HUD, poi trascinala ovunque sullo schermo. Mentre questa scheda è aperta, le righe sganciate mostrano le maniglie di trascinamento e gli altri elementi dell'HUD chiudono automaticamente lo spazio liberato."
L["Gap below"] = "Spazio sotto"
L["Global Cooldown"] = "Cooldown globale"
L["GCD Spiral Opacity"] = "Opacità spirale GCD"
L["How dark the Global Cooldown swipe appears on icons. Independent from Cooldown Spiral Opacity, so you can hide the cooldown spiral while keeping the GCD swipe visible (or vice versa)."] = "Quanto scura appare la lancetta del cooldown globale sulle icone. È indipendente da Opacità spirale cooldown, così puoi nascondere la spirale del cooldown mantenendo visibile la lancetta del GCD (o viceversa)."
L["Move separately"] = "Sposta separatamente"
L["Moves this ability row separately from the shared HUD stack so it can be placed anywhere on the screen. Turning it off returns the row to its configured layout order."] = "Sposta questa riga di abilità separatamente dalla pila HUD condivisa, così può essere collocata ovunque sullo schermo. Disattivandolo, la riga torna al suo ordine di disposizione configurato."
L["Reset Position"] = "Reimposta posizione"
L["Moves this independent row back to the position it would occupy in the shared HUD stack while keeping independent positioning enabled."] = "Riporta questa riga indipendente nella posizione che occuperebbe nella pila HUD condivisa, mantenendo attivo il posizionamento indipendente."
L["Horizontal Position"] = "Posizione orizzontale"
L["Fine-tunes this row's horizontal position relative to the center of the screen."] = "Regola con precisione la posizione orizzontale di questa riga rispetto al centro dello schermo."
L["Vertical Position"] = "Posizione verticale"
L["Fine-tunes this row's vertical position relative to the center of the screen."] = "Regola con precisione la posizione verticale di questa riga rispetto al centro dello schermo."
L["Independent row positioning cannot be edited during combat."] = "Il posizionamento indipendente delle righe non può essere modificato durante il combattimento."
L["Drag to move %s"] = "Trascina per spostare %s"
L["Secondary Row"] = "Riga secondaria"
L["Auxiliary Row"] = "Riga ausiliaria"
L["Row %d"] = "Riga %d"
L["|cffff0000Warning:|r LibSpellDB not found. Some features may not work."] = "|cffff0000Attenzione:|r LibSpellDB non trovato. Alcune funzioni potrebbero non funzionare."
L["Spec Detection Failed"] = "Rilevamento spec non riuscito"
L["LibSpellDB Missing"] = "LibSpellDB mancante"
L["LibSpellDB is required but not loaded."] = "LibSpellDB è richiesto ma non è caricato."
